// Some portions generated by Claude
import test from 'node:test';
import assert from 'node:assert/strict';
import { computeGraphLayout } from '../../../main/frontend/graph-explorer/graph-layout-engine.ts';
import { sharedHubNetwork, disconnectedNetwork } from './fixtures/layout-networks.mjs';
import { layoutMetrics } from './support/benchmark-layout.mjs';
import { createStarStressGraph } from '../../../main/frontend/graph-explorer/graph-fixtures.ts';
import { createLargeStressGraph } from '../../../main/frontend/graph-explorer/graph-fixtures.ts';
import {indexedIntersections} from './fixtures/layout-measurements.mjs';

test('hierarchy preserves directed rank order without altering RDF terms', async () => {
  const graph = {revision: 1, nodes: ['top', 'middle', 'bottom'].map(id => ({id, label: '<foreign> "label"', kind: 'iri'})),
    edges: [{id: 'a', source: 'top', target: 'middle', predicate: 'urn:p', label: 'p'}, {id: 'b', source: 'middle', target: 'bottom', predicate: 'urn:p', label: 'p'}]};
  const before = structuredClone(graph);
  const result = await computeGraphLayout(graph, {mode: 'hierarchy'});
  assert.ok(result.positions.get('top').y < result.positions.get('middle').y);
  assert.ok(result.positions.get('middle').y < result.positions.get('bottom').y);
  assert.deepEqual(graph, before);
});

test('incremental layout retains every fixed context coordinate and all parallel edges', async () => {
  const graph = {revision: 1, nodes: [
    {id: 'constructor', label: 'Context', kind: 'iri', x: 700, y: 80},
    {id: '__proto__', label: 'Pinned', kind: 'literal', pinned: true, x: 150, y: 80},
    {id: 'new', label: 'New', kind: 'blank', x: 700, y: 80}], edges: [
    {id: 'e1', source: 'constructor', target: 'new', predicate: 'urn:p', label: 'p'},
    {id: 'e2', source: 'constructor', target: 'new', predicate: 'urn:p2', label: 'p2'},
    {id: 'self', source: '__proto__', target: '__proto__', predicate: 'urn:p', label: 'p'}]};
  const result = await computeGraphLayout(graph, {incremental: true, movableNodeIds: new Set(['new'])});
  assert.deepEqual(result.positions.get('constructor'), {x: 700, y: 80});
  assert.deepEqual(result.positions.get('__proto__'), {x: 150, y: 80});
  assert.equal(result.positions.size, 3);
  assert.equal(result.bends.size, 3);
});

test('50,000-node organization retains all nodes using bounded coarse neighborhoods', async () => {
  const graph = createLargeStressGraph(50000, 1);
  const result = await computeGraphLayout(graph);
  assert.equal(result.positions.size, 50000);
  const centers = new Set();
  result.positions.forEach(p => {assert.ok(Number.isFinite(p.x) && Number.isFinite(p.y)); centers.add(`${p.x},${p.y}`);});
  assert.equal(centers.size, 50000);
  assert.equal(indexedIntersections(graph, result.positions), 0, 'distinct centers alone do not prove clear node cards');
});

test('empty and isolated-node layouts are finite and preserve pinned positions', async () => {
  assert.equal((await computeGraphLayout({nodes: [], edges: [], revision: 1})).positions.size, 0);
  const graph = {nodes: [{id: 'lone', label: 'Only node', kind: 'literal', x: -500, y: 40, pinned: true}], edges: [], revision: 1};
  assert.deepEqual((await computeGraphLayout(graph)).positions.get('lone'), {x: -500, y: 40});
});

test('a pure 300-leaf fan does not regress to stacked columns through its edges', async () => {
  const graph = createStarStressGraph(300, 1);
  const result = await computeGraphLayout(graph);
  const metrics = layoutMetrics(graph, result.positions);
  assert.equal(metrics.nodeOverlaps, 0);
  assert.ok(metrics.edgeNodeOverlaps <= 700, `edge-node conflicts: ${metrics.edgeNodeOverlaps}`);
});

test('shared-hub organization does not explode neighborhoods into distant sectors', async () => {
  const graph = sharedHubNetwork();
  const before = structuredClone(graph);
  const result = await computeGraphLayout(graph);
  const metrics = layoutMetrics(graph, result.positions);
  assert.equal(metrics.nodeOverlaps, 0);
  // Larger minimum card gaps intentionally add a little length (baseline 2191,
  // roomier policy 2231). Keep a bounded budget, not the rejected 2766-unit fan.
  // The organic engine draws the award's clusters around it in sectors, the
  // award's own links long by design (2460).
  assert.ok(metrics.p95Edge < 2600, `95th-percentile edge length: ${metrics.p95Edge}`);
  assert.ok(metrics.area < 40000000, `layout area: ${metrics.area}`);
  assert.ok(metrics.edgeCrossings < 300, `crossings: ${metrics.edgeCrossings}`);
  assert.deepEqual(graph, before);
});

test('disconnected components are packed without unrelated edges or overlaps', async () => {
  const graph = disconnectedNetwork();
  const result = await computeGraphLayout(graph);
  const metrics = layoutMetrics(graph, result.positions);
  assert.equal(metrics.nodeOverlaps, 0);
  assert.equal(metrics.edgeCrossings, 0);
  assert.ok(metrics.area < 6500000, `component packing area: ${metrics.area}`);
  assert.equal(result.positions.size, graph.nodes.length);
});
